// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerPrompt, filterTableBySearch } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(149000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/logout`);
    await page.goto(`${baseUrl}/admin/login`);

    await signIn(page, "admin@example.com", "admin");

    await dismissProjectOwnerPrompt(page);
    await page.goto(`${baseUrl}/admin/settings/policies`);
    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await expect(page.getByRole("cell", { name: "Administrator", exact: true })).toHaveText("Administrator");
    await expect(page.getByRole("cell", { name: "Public", exact: true })).toHaveText("Public");
    await expect(page.locator('[data-testid="v-table-skeleton"]')).toHaveCount(0);
    await expect(page.getByRole("row")).toHaveCount(3);

    await filterTableBySearch(page, "Public");

    await expect(page.getByRole("cell", { name: "Public", exact: true })).toHaveText("Public");
    await expect(page.getByRole("cell", { name: "Administrator", exact: true })).toHaveCount(0);
    await expect(page.locator('[data-testid="v-table-skeleton"]')).toHaveCount(0);
    await expect(page.getByRole("row")).toHaveCount(2);
});
